{"code":"import numpy as np,itertools
P={k:np.array(list(map(int,v))).reshape(3,3) for k,v in {'A':'010110011','T':'111001101','H':'110011101','G':'101110011','X':'111010010','Y':'111101101'}.items()}
def trans(a):
 qs=[]
 for k in range(4):qs.append(np.rot90(a,-k))
 for k in range(4):qs.append(np.rot90(np.fliplr(a),-k))
 return qs
pairs=[('A','T'),('T','H'),('G','X'),('X','Y')]
sol=[]
for mask in range(256):
 for const in [0,1]:
  ok=True
  for u,v in pairs:
   z=np.full((3,3),const,int)
   for j,q in enumerate(trans(P[u])):
    if mask>>j&1:z^=q
   if not np.array_equal(z,P[v]):ok=False;break
  if ok:sol.append((mask,const))
print('xor dihedral solutions',sol)
# enumerate one binary op between two transformed copies, with optional inversion each/output
ops={'xor':lambda a,b:a^b,'or':lambda a,b:a|b,'and':lambda a,b:a&b,'xnor':lambda a,b:1-(a^b),'nand':lambda a,b:1-(a&b),'nor':lambda a,b:1-(a|b)}
sol2=[]
for i,j in itertools.product(range(8),repeat=2):
 for name,op in ops.items():
  if all(np.array_equal(op(trans(P[u])[i],trans(P[u])[j]),P[v]) for u,v in pairs):sol2.append((i,j,name))
print('binary dihedral',sol2)
